window.RP_SESSION={"id":"S-007d18548d97","messages":[{"id":"RP-0159756","time":"2026-05-19T10:19:00+09:00","room":"RP","name":"베스퍼 디 하운드","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"···.","characters":["P-051c3e67e69c"]},{"id":"RP-0159757","time":"2026-05-19T10:20:00+09:00","room":"RP","name":"베스퍼 디 하운드","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"자박자박, 가벼운 발걸음이 한 무덤을 울렸다.\n\n잔디밭 아래에 가볍게 앉자, 꽃들이 말갛게 피어났다.\n\n베스퍼는 이윽고 천천히 류트를 들었다.","characters":["P-051c3e67e69c"]},{"id":"RP-0159758","time":"2026-05-19T10:21:00+09:00","room":"RP","name":"베스퍼 디 하운드","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"https://youtu.be/b89kpj7t93E?si=GyWDg7kOjfh1XHe6","characters":["P-051c3e67e69c"]},{"id":"RP-0159759","time":"2026-05-19T10:23:00+09:00","room":"RP","name":"베스퍼 디 하운드","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"연한 목소리가 빈 공간을 채웁니다.\n\n천천히 연주되는 류트.\n\n그 옆에 존재하는 시들시들한 꽃.","characters":["P-051c3e67e69c"]},{"id":"RP-0159760","time":"2026-05-19T10:23:00+09:00","room":"RP","name":"베스퍼 디 하운드","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"이윽고···.\n\n밝게 웃고 있는 초상화.\n\n열심히 모아 보관한 돈입니다.\n\n······.","characters":["P-051c3e67e69c"]},{"id":"RP-0159761","time":"2026-05-19T10:24:00+09:00","room":"RP","name":"베스퍼 디 하운드","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그리운 한 마음 담아, 옅은 목소리가 공간을 채웁니다.","characters":["P-051c3e67e69c"]},{"id":"RP-0159762","time":"2026-05-19T10:24:00+09:00","room":"RP","name":"베스퍼 디 하운드","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"들판에 바람이 일렁이고, 꽃들 역시도 바스라질 듯 흔들립니다.","characters":["P-051c3e67e69c"]},{"id":"RP-0159763","time":"2026-05-19T10:25:00+09:00","room":"RP","name":"베스퍼 디 하운드","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"나를 위해 제 몸 받친 당신에게 무엇 못해주랴.\n\n당신이 나아갈 바다는, 당신이 보낼 항해는 부디 부드럽기를.","characters":["P-051c3e67e69c"]},{"id":"RP-0159764","time":"2026-05-19T10:26:00+09:00","room":"RP","name":"베스퍼 디 하운드","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"안녕, 나의 친구.\n\n당신이 내어준 이름은 손에 꼭 쥘게.\n\n······.\n\n작별인사를 할 시간이에요.\n\n돌아오면 내가 이곳에 있다는 걸 기억해주기를.","characters":["P-051c3e67e69c"]},{"id":"RP-0159765","time":"2026-05-19T11:22:00+09:00","room":"RP","name":"베스퍼 디 하운드","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"골기아의 근방, 작은 시골 마을서 베스퍼는 남은 짐을 챙겨올 틈에 친구에게\n\n작별인사를 전했다.\n\n······ 친구보다는, 가족에 더 가까운. 그런 아이.","characters":["P-051c3e67e69c"]},{"id":"RP-0159766","time":"2026-05-19T11:22:00+09:00","room":"RP","name":"베스퍼 디 하운드","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"두 손으로, 따스한 피를 느끼게 된···.\n\n어쩔 수 없이 해친.\n\n첫번째의 생명.","characters":["P-051c3e67e69c"]},{"id":"RP-0159767","time":"2026-05-19T11:23:00+09:00","room":"RP","name":"베스퍼 디 하운드","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그러나 베스퍼는 미소짓고 있었다. 천천히 보듬았다.","characters":["P-051c3e67e69c"]},{"id":"RP-0159768","time":"2026-05-19T12:45:00+09:00","room":"RP","name":"베스퍼 디 하운드","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-051c3e67e69c"]},{"id":"RP-0159769","time":"2026-05-19T12:45:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
